using System.Data.Common;
using QuickSql.Metadata;
using QuickSql.Providers.PostgreSqlBase;

namespace QuickSql.Providers.Kingbase;

/// <summary>金仓 KES V8 的驱动槽位：零覆写壳，产出与 PostgreSqlProviderBase 逐字同形。
/// 厂商行点名的三坑落点：双引号大小写敏感已落进血统的 IdentifierPolicy.PostgreSQL；
/// SERIAL 与 IDENTITY 基类选了 GENERATED BY DEFAULT AS IDENTITY，金仓 V8 内核认不认未实测；
/// Oracle 兼容模式开关会换掉分页与 NVARCHAR2 行为——一颗连接串参数换掉方言假设，SPI 没有"兼容模式"槽位，未建模。</summary>
[QuickSqlProvider(DbKind.Kingbase)]
public sealed class KingbaseProvider : PostgreSqlProviderBase
{
    /// <summary>内建表里的 key。assembly 按厂商文档填 Kdbndp（金仓自研驱动），现场也可以注 Npgsql——两条都走同一份注入路径。</summary>
    public const string DriverKey = "kingbase";

    public KingbaseProvider(DbProviderFactory driverFactory)
        : base(DbKind.Kingbase, driverFactory)
    {
    }
}
